import React, { useState } from "react";
import { predict } from "../api";

// Example lists — replace with real model categories
const INDUSTRIES = [
  { label: "Technology", value: 0 },
  { label: "Finance", value: 1 },
  { label: "Healthcare", value: 2 },
  { label: "Retail", value: 3 }
];

const COUNTRIES = [
  { label: "USA", value: 0 },
  { label: "Kenya", value: 1 },
  { label: "India", value: 2 },
  { label: "Germany", value: 3 }
];

export default function Predict() {
  const [formData, setFormData] = useState({
    industry_enc: 0,
    country_enc: 0,
    company_age: 5,
    avg_size: 50,
    current_employee_estimate: 50,
    total_employee_estimate: 50,
    model_type: "rf_category"
  });

  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  // Update form values
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: Number(value) }));
  };

  // Submit prediction
  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setResult(null);

    try {
      const res = await predict(formData);
      setResult(res);

      if (res && !res.error) saveToHistory(res);
    } catch (err) {
      setResult({ error: err.message || "API request failed" });
    }

    setLoading(false);
  };

  // Save to history
  const saveToHistory = (res) => {
    const stored = JSON.parse(localStorage.getItem("predictionHistory") || "[]");
    stored.push({ ...formData, result: res });
    localStorage.setItem("predictionHistory", JSON.stringify(stored));
  };

  // Confidence color
  const getConfidenceColor = (confidence) => {
    if (confidence == null) return "#000";
    if (confidence >= 0.75) return "#2e7d32";
    if (confidence >= 0.5) return "#f9a825";
    return "#c62828";
  };

  return (
    <div style={container}>
      <h1 style={title}>Company Growth Prediction</h1>

      <form onSubmit={handleSubmit} style={formGrid}>
        {/* Industry */}
        <div style={field}>
          <label>Industry</label>
          <select
            name="industry_enc"
            value={formData.industry_enc}
            onChange={handleChange}
            style={input}
          >
            {INDUSTRIES.map((i) => (
              <option key={i.value} value={i.value}>
                {i.label}
              </option>
            ))}
          </select>
        </div>

        {/* Country */}
        <div style={field}>
          <label>Country</label>
          <select
            name="country_enc"
            value={formData.country_enc}
            onChange={handleChange}
            style={input}
          >
            {COUNTRIES.map((c) => (
              <option key={c.value} value={c.value}>
                {c.label}
              </option>
            ))}
          </select>
        </div>

        {/* Sliders */}
        {[
          { name: "company_age", label: "Company Age", min: 1, max: 50 },
          { name: "avg_size", label: "Average Company Size", min: 1, max: 1000 },
          { name: "current_employee_estimate", label: "Current Employees", min: 1, max: 1000 },
          { name: "total_employee_estimate", label: "Total Employees", min: 1, max: 5000 }
        ].map((field) => (
          <div key={field.name} style={field}>
            <label>
              {field.label}: <strong>{formData[field.name]}</strong>
            </label>
            <input
              type="range"
              name={field.name}
              min={field.min}
              max={field.max}
              value={formData[field.name]}
              onChange={handleChange}
              style={{ width: "100%" }}
            />
          </div>
        ))}

        {/* Model Type */}
        <div style={field}>
          <label>Model Type</label>
          <select
            name="model_type"
            value={formData.model_type}
            onChange={handleChange}
            style={input}
          >
            <option value="rf_category">RF Category</option>
            <option value="rf_level">RF Level</option>
            <option value="xgb_category">XGB Category</option>
            <option value="xgb_level">XGB Level</option>
          </select>
        </div>

        <button type="submit" disabled={loading} style={predictButton}>
          {loading ? "Predicting..." : "Run Prediction"}
        </button>
      </form>

      {/* Result */}
      {result && (
        <div style={resultCard}>
          {result.error ? (
            <>
              <h3 style={{ color: "#c62828" }}>Error</h3>
              <p>{result.error}</p>
            </>
          ) : (
            <>
              <h3>Prediction Result</h3>
              <p><strong>Cluster:</strong> {result?.cluster ?? "-"}</p>
              <p><strong>Prediction:</strong> {result?.prediction ?? "-"}</p>
              <p>
                <strong>Confidence:</strong>{" "}
                <span style={{ color: getConfidenceColor(result?.confidence) }}>
                  {result?.confidence
                    ? (result.confidence * 100).toFixed(2) + "%"
                    : "-"}
                </span>
              </p>

              <button
                onClick={() => saveToHistory(result)}
                style={saveButton}
              >
                Save to History
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
}

/* ---------- Styles ---------- */

const container = {
  width: "100%",
  padding: "10px 10px",
  boxSizing: "border-box"
};

const title = {
  marginBottom: "20px"
};

const formGrid = {
  display: "grid",
  gap: "18px"
};

const field = {
  display: "flex",
  flexDirection: "column",
  gap: "6px"
};

const input = {
  padding: "10px",
  borderRadius: "6px",
  border: "1px solid #ccc"
};

const predictButton = {
  padding: "12px",
  background: "#4CAF50",
  color: "white",
  border: "none",
  borderRadius: "6px",
  fontWeight: "bold",
  cursor: "pointer"
};

const resultCard = {
  marginTop: "25px",
  padding: "20px",
  borderRadius: "10px",
  background: "#f5f7fb",
  border: "1px solid #e0e0e0"
};

const saveButton = {
  marginTop: "10px",
  padding: "10px 14px",
  background: "#2196F3",
  color: "white",
  border: "none",
  borderRadius: "6px",
  cursor: "pointer"
};
